import { useEffect,useRef, useState } from 'react'
import type { ChangeEvent, CSSProperties, FormEvent } from 'react'
import type { DemoStore, Journal, PageProps, RecordItem } from './domain'
import { themeOptions } from './domain'
import { exportBackup, exportMuseum, initialStore, isDemoStore, makeId, today } from './data'
import { Empty, Icon, Modal } from './ui'
import { SyncLab } from './SyncLab'
import { AssistantCapabilities } from './AssistantCapabilities'
import {getAssistantModelConfig,type AssistantModelConfig} from './model-assistant'
import {generateCreativeDraft} from './model-assistant'
import {canCite} from './assistant-search'
import {formalCloud} from './cloud-client'
import type {CareSignal,SecureCapsule} from './cloud-contract'
import './life-pages.css'

const dayLabel = (date: string) => date ? date.replaceAll('-', '.') : '还没有确定日期'
const nextDay = (offset = 1) => { const date = new Date(`${today()}T12:00:00Z`); date.setUTCDate(date.getUTCDate() + offset); return date.toISOString().slice(0, 10) }
const clamp = (value: number) => Math.max(0, Math.min(100, value))
const stamp = () => new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date())

function RecordPreview({ record, onClose }: { record: RecordItem; onClose: () => void }) {
  return <Modal title={record.title} onClose={onClose}><div className="life-record-preview">{record.image && <img src={record.image} alt={record.title}/>}<span className="tag">{record.kind} · {dayLabel(record.date)}</span><p>{record.body}</p><details open><summary>这段回忆的来源</summary><p>{record.source || '手动记录，暂无其他来源'}</p></details></div></Modal>
}

export function CarePage({ store, update, notify }: PageProps) {
  const [draft, setDraft] = useState(store.care.draft)
  const [draftId, setDraftId] = useState<string | null>(() => store.journals.find(item => item.title.startsWith('私人草稿 · ') && item.body === store.care.draft)?.id ?? null)
  const [viewDraft, setViewDraft] = useState<Journal | null>(null)
  const [planOpen, setPlanOpen] = useState(false)
  const [planTitle, setPlanTitle] = useState(`给${store.settings.partnerName}一句鼓励`)
  const [planDate, setPlanDate] = useState(nextDay())
  const [planTime, setPlanTime] = useState('13:30')
  const [cycle, setCycle] = useState(store.care.cycleStart || today())
  const [cycleDelete, setCycleDelete] = useState(false)
  const [draftDelete, setDraftDelete] = useState<string | null>(null)
  const [careSession,setCareSession]=useState<{userId:string}|null>(null),[careSpace,setCareSpace]=useState<string>(''),[signals,setSignals]=useState<CareSignal[]>([]),[shareMessage,setShareMessage]=useState(''),[shareHours,setShareHours]=useState(8),[careBusy,setCareBusy]=useState(false),[careError,setCareError]=useState('')
  const privateDrafts = store.journals.filter(item => item.title.startsWith('私人草稿 · '))
  const needs = [{ name: '想安静', icon: 'moon', desc: '先留一点自己的时间' }, { name: '想聊聊', icon: 'message', desc: '听听彼此今天的故事' }, { name: '想被听见', icon: 'heart', desc: '陪我说，不急着给答案' }, { name: '一起想办法', icon: 'spark', desc: '我们一起慢慢解决' }]
  const refreshCare=async()=>{const session=await formalCloud.getSession();if(!session.ok||!session.data){setCareSession(null);setCareSpace('');setSignals([]);return}const space=await formalCloud.getCurrentSpace();if(!space.ok||!space.data){setCareSession(session.data);setCareSpace('');setSignals([]);return}const result=await formalCloud.careSignals(space.data.space.id);if(!result.ok)throw new Error(result.error.message);setCareSession(session.data);setCareSpace(space.data.space.id);setSignals(result.data)}
  useEffect(()=>{let active=true;const run=()=>void refreshCare().catch(error=>{if(active)setCareError(error instanceof Error?error.message:'关怀分享读取失败')});run();const timer=window.setInterval(run,15_000);return()=>{active=false;window.clearInterval(timer)}},[])
  const publishCare=async()=>{if(!careSpace)return;setCareBusy(true);setCareError('');try{const result=await formalCloud.publishCare(careSpace,{need:store.care.need as CareSignal['need'],message:shareMessage.trim(),hours:shareHours});if(!result.ok)throw new Error(result.error.message);update(value=>({...value,care:{...value.care,shared:true}}),'关怀需要已分享，可随时撤回');await refreshCare()}catch(error){setCareError(error instanceof Error?error.message:'分享失败')}finally{setCareBusy(false)}}
  const revokeCare=async()=>{if(!careSpace)return;setCareBusy(true);setCareError('');try{const result=await formalCloud.revokeCare(careSpace);if(!result.ok)throw new Error(result.error.message);update(value=>({...value,care:{...value.care,shared:false}}),'关怀分享已撤回');await refreshCare()}catch(error){setCareError(error instanceof Error?error.message:'撤回失败')}finally{setCareBusy(false)}}
  const ownSignal=signals.find(signal=>signal.userId===careSession?.userId),partnerSignals=signals.filter(signal=>signal.userId!==careSession?.userId)
  const saveDraft = () => {
    const body = draft.trim()
    if (!body) return notify('先写下一点想说的话吧')
    const duplicate = privateDrafts.find(item => item.body === body && item.id !== draftId)
    if (duplicate && !draftId) {
      update(s => ({ ...s, care: { ...s.care, draft: body } }), '这份私人草稿已经保存')
      setDraftId(duplicate.id)
      return
    }
    const existing = privateDrafts.find(item => item.id === draftId)
    const journal: Journal = { id: existing?.id ?? makeId(), title: `私人草稿 · ${body.split('\n')[0].slice(0, 18)}`, body, date: today(), type: '日常' }
    update(s => ({ ...s, care: { ...s.care, draft: body }, journals: existing ? s.journals.map(item => item.id === existing.id ? journal : item) : [journal, ...s.journals] }), existing ? '私人草稿已更新，没有新增重复条目' : '私人草稿已保存在当前浏览器')
    setDraftId(journal.id)
  }
  const addPlan = (event: FormEvent) => {
    event.preventDefault()
    if (!planTitle.trim()) return
    update(s => ({ ...s, plans: [{ id: makeId(), title: planTitle.trim(), date: planDate, time: planTime, kind: '提醒', status: 'todo',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',recurrence:'none',reminderMinutes:planTime?0:null,completedOccurrences:[] }, ...s.plans] }), '关怀计划已加入日历；页面打开时会检查页内提醒')
    setPlanOpen(false)
  }
  return <div className="life-page">
    <div className="life-intro"><span className="life-kicker">CARE, IN YOUR OWN WAY</span><h2>关心，从听见彼此开始。</h2><p>不替你猜情绪，也不催你回应。把需要说清楚，就是很好的开始。</p></div>
    <div className="life-care-grid">
      <section className="panel life-needs"><div className="panel-heading"><div><span className="life-kicker">此刻的我</span><h3>今天，我需要什么</h3></div><span className="tag">{ownSignal?'已分享 · 可撤回':'仅自己可见'}</span></div>{partnerSignals.map(signal=><div className="life-share-preview is-received" key={signal.userId}><Icon name="heart" size={18}/><p><strong>{signal.displayName}现在「{signal.need}」</strong>{signal.message&&<><br/><span>{signal.message}</span></>}<br/><small>有效至 {new Date(signal.expiresAt).toLocaleString('zh-CN')} · 只包含对方主动分享的内容</small></p><span>对方分享</span></div>)}<div className="life-need-options">{needs.map(need=><button key={need.name} className={`life-need ${store.care.need===need.name?'is-selected':''}`} aria-pressed={store.care.need===need.name} onClick={()=>update(s=>({...s,care:{...s.care,need:need.name}}),`已记下：${need.name}`)}><Icon name={need.icon} size={23}/><strong>{need.name}</strong><span>{need.desc}</span></button>)}</div>{careSpace?<div className="life-care-share"><label className="field"><span>可选的一句话（不会包含私人草稿）</span><input maxLength={280} value={shareMessage} onChange={e=>setShareMessage(e.target.value)} placeholder="例如：现在先听我说完就好。"/></label><label className="field"><span>分享多久</span><select value={shareHours} onChange={e=>setShareHours(Number(e.target.value))}><option value={1}>1 小时</option><option value={4}>4 小时</option><option value={8}>8 小时</option><option value={24}>24 小时</option><option value={72}>3 天</option></select></label>{ownSignal?<div className="life-share-preview"><Icon name="heart" size={18}/><p><strong>已分享「{ownSignal.need}」</strong><br/><small>有效至 {new Date(ownSignal.expiresAt).toLocaleString('zh-CN')}；私人草稿和周期信息没有发送。</small></p><span className="core-inline"><button className="btn secondary small" disabled={careBusy} onClick={()=>void publishCare()}>更新分享</button><button className="btn secondary small" disabled={careBusy} onClick={()=>void revokeCare()}>撤回分享</button></span></div>:<button className="btn primary" disabled={careBusy} onClick={()=>void publishCare()}>{careBusy?'正在分享…':`分享给 ${store.settings.partnerName}`}</button>}</div>:<p className="life-small-note">登录并加入共同空间后，可以把所选需要和一条短消息分享给对方；私人草稿不会发送。</p>}{careError&&<p role="alert" className="life-small-note">{careError}</p>}</section>
      <section className="panel life-followup"><span className="life-kicker">在意的小事</span><h3>让关心，发生在恰好的时候</h3><div className="life-care-flower" aria-hidden="true">✳</div><p>一句提前的鼓励，或者结束后留一点空间。关怀的节奏，由你们决定。</p><ol><li><span>01</span><div><strong>事前，表达支持</strong><small>问问对方需要什么</small></div></li><li><span>02</span><div><strong>事后，留一点空间</strong><small>不连续追问，不催促回应</small></div></li><li><span>03</span><div><strong>愿意时，再聊聊</strong><small>记住感受，比追问结果重要</small></div></li></ol><button className="btn primary" onClick={() => setPlanOpen(true)}><Icon name="plus" size={16}/>安排一份关心</button></section>
      <section className="panel life-draft"><div className="panel-heading"><div><span className="life-kicker">慢慢说</span><h3>有些话，可以先写给自己</h3></div><Icon name="lock" size={21}/></div><label className="field"><span>发生了什么？我希望被怎样对待？</span><textarea value={draft} onChange={e => setDraft(e.target.value)} placeholder="例如：今天有一点累，我想先安静一下。等准备好了，再认真听你说。" rows={6}/></label><div className="life-form-bottom"><span className="muted">{draftId ? '正在修改已保存的私人草稿' : '只保存在此浏览器 · 不会自动发送'}</span><div className="life-draft-buttons">{draftId && <button className="btn secondary small" onClick={() => { setDraftId(null); setDraft(''); notify('可以开始另一份私人草稿，原稿仍已保留') }}>另写一份</button>}<button className="btn primary" onClick={saveDraft}>{draftId ? '更新私人草稿' : '保存私人草稿'}</button></div></div><div className="life-draft-history"><h4>已保存的草稿 <span>{privateDrafts.length}</span></h4>{privateDrafts.length ? privateDrafts.slice(0, 5).map(item => <div className="life-saved-draft" key={item.id}><button onClick={() => setViewDraft(item)}><strong>{item.title.replace('私人草稿 · ', '')}</strong><small>{dayLabel(item.date)}</small></button><button className="btn small" aria-label={`删除草稿：${item.title}`} onClick={() => setDraftDelete(item.id)}><Icon name="trash" size={15}/></button></div>) : <p className="muted">愿意写下的每句话，都有自己的位置。</p>}</div></section>
      <section className="panel life-cycle"><div className="panel-heading"><div><span className="life-kicker">照顾自己的节奏</span><h3>私人周期记录</h3></div><span className="tag"><Icon name="lock" size={12}/>仅自己</span></div><p className="muted">只记录你填写的日期，不推测情绪，不给出健康判断。</p>{store.care.cycleStart && <div className="life-cycle-date"><small>最近记录的起始日</small><strong>{dayLabel(store.care.cycleStart)}</strong><button className="btn small" onClick={() => setCycleDelete(true)}>删除这条记录</button></div>}<label className="field"><span>起始日期</span><input type="date" max={today()} value={cycle} onChange={e => setCycle(e.target.value)}/></label><button className="btn secondary" disabled={!cycle || cycle > today()} onClick={() => update(s => ({ ...s, care: { ...s.care, cycleStart: cycle } }), '私人日期已保存')}>{store.care.cycleStart ? '更新日期' : '记下这一天'}</button><div className="life-small-note"><Icon name="lock" size={15}/><span>这个日期不会进入青鸟问答，也不会包含在纪念馆中。</span></div></section>
    </div>
    {planOpen && <Modal title="安排一份关心" onClose={() => setPlanOpen(false)}><form onSubmit={addPlan} className="life-form"><label className="field"><span>想做的事</span><input autoFocus required maxLength={80} value={planTitle} onChange={e => setPlanTitle(e.target.value)}/></label><div className="form-grid"><label className="field"><span>日期</span><input type="date" required value={planDate} onChange={e => setPlanDate(e.target.value)}/></label><label className="field"><span>时间</span><input type="time" value={planTime} onChange={e => setPlanTime(e.target.value)}/></label></div><p className="muted">它会出现在日历中，并在页面打开或恢复可见时检查提醒；不会自动给对方发送消息。</p><button className="btn primary" type="submit">加入日历</button></form></Modal>}
    {viewDraft && <Modal title="我的私人草稿" onClose={() => setViewDraft(null)}><article className="life-letter"><time>{dayLabel(viewDraft.date)}</time><p>{viewDraft.body}</p></article><button className="btn secondary" onClick={() => { setDraft(viewDraft.body); setDraftId(viewDraft.id); setViewDraft(null); notify('已放入编辑框，可以继续修改') }}>继续写</button></Modal>}
    {cycleDelete && <Modal title="删除私人周期记录？" onClose={() => setCycleDelete(false)}><p>删除后将不再显示此日期。</p><div className="life-modal-actions"><button className="btn secondary" onClick={() => setCycleDelete(false)}>保留</button><button className="btn danger" onClick={() => { update(s => ({ ...s, care: { ...s.care, cycleStart: '' } }), '私人日期已删除'); setCycleDelete(false) }}>确认删除</button></div></Modal>}
    {draftDelete && <Modal title="删除这份私人草稿？" onClose={() => setDraftDelete(null)}><p>删除后无法直接撤销，请确认已保留需要的内容。</p><div className="life-modal-actions"><button className="btn secondary" onClick={() => setDraftDelete(null)}>保留</button><button className="btn danger" onClick={() => { update(s => ({ ...s, care: draftId === draftDelete ? { ...s.care, draft: '' } : s.care, journals: s.journals.filter(item => item.id !== draftDelete) }), '私人草稿已删除'); if (draftId === draftDelete) { setDraftId(null); setDraft('') }; setDraftDelete(null) }}>确认删除</button></div></Modal>}
  </div>
}

const rooms = [{ id: 'study' as const, name: '窗边书房', desc: '一盏暖灯，一页好故事', image: '/assets/room-study.png' }, { id: 'garden' as const, name: '庭院春深', desc: '听风，等花慢慢开', image: '/assets/room-garden.png' }, { id: 'cosmos' as const, name: '星河小屋', desc: '把心愿寄给远处的星星', image: '/assets/room-cosmos.png' }]

export function PetScene({ store, update, petAction, compact = false }: PageProps & { compact?: boolean }) {
  const [decorate, setDecorate] = useState(false)
  const [actionKey, setActionKey] = useState(0)
  const [motion,setMotion]=useState('idle')
  const [bubble, setBubble] = useState(store.pet.pose === 'sleep' ? '正在安静休息，点一点就可以叫醒我。' : '你来啦，今天也一起慢慢过。')
  const pet = store.pet
  const stage = pet.feathers >= 150 ? '并肩的小旅人' : pet.feathers >= 60 ? '好奇的探索家' : '初见的小伙伴'
  const wake = () => {
    const wasSleeping = pet.pose === 'sleep'
    setBubble(wasSleeping ? '睡饱啦，今天又想和你一起玩！' : '我在这里，陪你慢慢过今天。')
    setActionKey(0)
    setMotion('idle')
    if(petAction){petAction({kind:'wake'});return}
    update(s => ({ ...s, pet: { ...s.pet, pose: 'idle', log: wasSleeping ? [`${stamp()} · ${s.pet.name}睡醒了，准备继续今天的小冒险。`, ...s.pet.log].slice(0, 60) : s.pet.log } }), wasSleeping ? `${pet.name}醒来啦` : `${pet.name}回到了待机姿态`)
  }
  const act = (kind: 'touch' | 'feed' | 'rest'|'preen'|'deliver'|'explore') => {
    const words={touch:'被温柔摸摸，心里暖暖的。',feed:'谢谢你的点心，补充好能量啦！',rest:'找一个舒服的角落，休息一小会儿。',preen:'把每一根羽毛都梳理整齐。',deliver:'叼起一封小信，准备送到重要的人身边。',explore:'歪着头看看，今天又发现了新角落。'}[kind]
    setBubble(words);setMotion(kind); setActionKey(value => value + 1)
    if(petAction){petAction({kind});return}
    update(s => ({ ...s, pet: { ...s.pet,
      energy: clamp(s.pet.energy + (kind === 'rest' ? 18 : kind === 'feed' ? 12 : kind==='explore'?-4:-1)),
      comfort: clamp(s.pet.comfort + (kind === 'touch' ? 10 : kind==='preen'?6:kind==='deliver'?3:4)),
      curiosity: clamp(s.pet.curiosity + (kind === 'explore'?10:kind==='deliver'?6:kind === 'rest' ? -2 : 3)),
      feathers: s.pet.feathers + (kind === 'rest'||kind==='preen'?1:kind === 'feed' ? 3 : 2),
      pose: kind === 'rest' ? 'sleep' : kind === 'feed' ? 'eat' : kind==='preen'?'idle':'happy',
      log: [`${stamp()} · ${s.pet.name}${words}`, ...s.pet.log].slice(0, 60),
    } }), kind === 'touch' ? '安心 +10 · 羽光 +2' : kind === 'feed' ? '能量 +12 · 羽光 +3' : kind==='rest'?'能量 +18 · 羽光 +1':kind==='preen'?'安心 +6 · 羽光 +1':kind==='deliver'?'好奇 +6 · 羽光 +2':'好奇 +10 · 羽光 +2')
  }
  return <section className={`life-pet-scene panel ${compact ? 'is-compact' : ''}`}>
    <div className="life-pet-top"><div><span className="life-kicker">我们的鹊巢</span><h3>{pet.name}的小小世界</h3></div><span className="life-feathers">✦ {pet.feathers} 羽光</span></div>
    <div className={`life-room room-${pet.room}`} style={{ backgroundImage: `url(${rooms.find(room => room.id === pet.room)?.image})` }}><div className="life-room-light"/>{compact && <><div className="life-scene-card life-scene-card-left"><span>我们的小伙伴</span><strong>{pet.name}<small>{stage}</small></strong></div><div className="life-scene-card life-scene-card-right"><span>{rooms.find(room => room.id === pet.room)?.name}</span><strong>✦ {pet.feathers}<small>羽光</small></strong></div></>}<div className="life-pet-bubble" aria-live="polite">{bubble}</div><button type="button" key={actionKey} className={`life-pet-sprite pose-${pet.pose} action-${motion} ${actionKey ? 'has-action' : ''}`} onClick={wake} aria-label={pet.pose === 'sleep' ? `唤醒${pet.name}` : `让${pet.name}恢复待机姿态`} title={pet.pose === 'sleep' ? '轻轻唤醒' : '点一点，回到待机姿态'}/><div className="life-room-caption"><span>{rooms.find(room => room.id === pet.room)?.name}</span><small>{stage}</small></div></div>
    <div className="life-pet-meters">{[{ label: '能量', value: pet.energy }, { label: '好奇', value: pet.curiosity }, { label: '安心', value: pet.comfort }].map(item => <div key={item.label}><span>{item.label}<b>{item.value}</b></span><progress max={100} value={item.value} aria-label={item.label}/></div>)}</div>
    <div className="life-pet-actions"><button onClick={() => act('touch')}><Icon name="heart" size={18}/><span>摸摸</span></button><button onClick={() => act('feed')}><Icon name="cup" size={18}/><span>喂点心</span></button><button onClick={() => pet.pose === 'sleep' ? wake() : act('rest')}><Icon name={pet.pose === 'sleep' ? 'sun' : 'moon'} size={18}/><span>{pet.pose === 'sleep' ? '唤醒' : '休息'}</span></button><button onClick={() => setDecorate(true)}><Icon name="home" size={18}/><span>布置</span></button>{!compact&&<><button onClick={()=>act('preen')}><Icon name="feather" size={18}/><span>梳羽</span></button><button onClick={()=>act('deliver')}><Icon name="mail" size={18}/><span>送信</span></button><button onClick={()=>act('explore')}><Icon name="search" size={18}/><span>探索</span></button></>}</div>
    {decorate && <Modal title="给小鹊换个喜欢的角落" onClose={() => setDecorate(false)} wide><div className="life-room-options">{rooms.map(room => <button key={room.id} className={pet.room === room.id ? 'is-selected' : ''} aria-pressed={pet.room === room.id} onClick={() => { if(petAction){petAction({kind:'room',room:room.id});setDecorate(false);return} update(s => ({ ...s, pet: { ...s.pet, room: room.id, log: [`${stamp()} · 为${s.pet.name}布置了${room.name}。`, ...s.pet.log].slice(0, 60) } }), `已换成${room.name}`); setDecorate(false); setBubble('新家也很喜欢，因为有你在。') }}><img src={room.image} alt={room.name}/><strong>{room.name}</strong><span>{room.desc}</span>{pet.room === room.id && <b>正在使用</b>}</button>)}</div></Modal>}
  </section>
}

export function NestPage(props: PageProps) {
  const { store, update, go, notify,petAction,petGrowthSources=[] } = props
  const [renaming, setRenaming] = useState(false)
  const [name, setName] = useState(store.pet.name)
  const [record, setRecord] = useState<RecordItem | null>(null)
  const [journey, setJourney] = useState(false)
  const [journeyPlan, setJourneyPlan] = useState('')
  const memories = store.records.filter(item => item.status === 'confirmed' && item.kind === '回忆')
  const wishes = store.plans.filter(item => item.status === 'todo')
  const linkedJourney = store.pet.log.find(item => item.includes('开始心愿旅程'))
  const rename = (event: FormEvent) => { event.preventDefault(); if (!name.trim()) return;if(petAction)petAction({kind:'rename',name:name.trim()});else update(s => ({ ...s, pet: { ...s.pet, name: name.trim(), log: [`${stamp()} · 小伙伴有了新名字：${name.trim()}。`, ...s.pet.log] } }), '新的名字，新的故事'); setRenaming(false) }
  return <div className="life-page">
    <div className="life-intro life-intro-row life-nest-intro"><div><span className="life-kicker">A LITTLE HOME FOR TWO</span><h2>一起，把小日子养大。</h2><p>每一次温柔的照顾，都会被小鹊记住。没有打卡，没有错过的惩罚。</p></div><button className="btn secondary" onClick={() => { setName(store.pet.name); setRenaming(true) }}><Icon name="edit" size={16}/>给小鹊改名</button></div>
    <div className="life-nest-grid"><PetScene {...props}/><section className="panel life-pet-letter"><span className="life-kicker">小鹊来信</span><div className="life-postmark" aria-hidden="true">鹊<br/>信</div><h3>陪伴，不需要很用力。</h3><p>给我一点小点心，<br/>或者只是来坐一坐。</p><p>你们在一起的普通日子，<br/>就是我最喜欢的故事。</p><small>—— 你们的 {store.pet.name}</small><div className="life-pet-note"><Icon name="lock" size={14}/><span>本地养成演示 · 关闭 AI 也能完整玩耍</span></div></section></div>
    <div className="life-nest-cards">
      <section className="panel life-postcards"><div className="panel-heading"><div><span className="life-kicker">把喜欢带回家</span><h3>回忆明信片</h3></div><Icon name="image" size={20}/></div>{memories.length ? <div className="life-mini-postcards">{memories.slice(0, 2).map(item => <button key={item.id} onClick={() => setRecord(item)}>{item.image ? <img src={item.imageThumbnail??item.image} alt=""/> : <div className="life-postcard-plain">一段好时光</div>}<strong>{item.title}</strong><time>{dayLabel(item.date)}</time></button>)}</div> : <Empty text="确认一条回忆，给小鹊带来第一张明信片。"/>}</section>
      <section className="panel life-journey"><span className="life-kicker">下一站，和你</span><h3>心愿旅程</h3><div className="life-journey-line" aria-hidden="true"><span>⌂</span><i/><span>✦</span><i/><span>⚑</span></div><p>{linkedJourney ? linkedJourney.slice(linkedJourney.indexOf('开始心愿旅程')) : '挑一件想一起做的事，让小鹊也加入期待。'}</p><button className="btn secondary" onClick={() => { setJourneyPlan(wishes[0]?.id ?? ''); setJourney(true) }}>选择一个心愿</button></section>
      <section className="panel life-capsule-card"><span className="life-kicker">给未来的一封信</span><h3>时光胶囊</h3><div className="life-envelope-art" aria-hidden="true"><span>♥</span></div><p>把今天的期待，留给未来的我们。</p><button className="btn secondary" onClick={() => go('create','时光胶囊')}>去写时光胶囊 <Icon name="arrow" size={15}/></button></section>
    </div>
    <div className="life-nest-bottom"><section className="panel life-collection"><div className="panel-heading"><div><span className="life-kicker">沿途的小宝物</span><h3>贝壳收藏架</h3></div><span className="tag">{Math.min(memories.length, 6)} 件珍藏</span></div><div className="life-shells">{memories.slice(0, 6).map((item, index) => <button key={item.id} onClick={() => setRecord(item)}><span aria-hidden="true">{['◒', '✳', '❋', '◈', '✦', '◉'][index]}</span><strong>{item.title}</strong><small>查看回忆来源</small></button>)}</div>{!memories.length && <p className="muted">每段被确认的回忆，都可以变成这里的小宝物。</p>}</section><section className="panel life-growth"><div className="panel-heading"><div><span className="life-kicker">一点点长大</span><h3>成长手记</h3></div><span className="tag">{petGrowthSources.length} 条回忆来源</span></div>{petGrowthSources.length?<div className="life-growth-sources">{petGrowthSources.slice(0,6).map(source=><button className="life-growth-source" key={source.sourceId} onClick={()=>{const record=memories.find(item=>item.id===source.sourceId);if(record)setRecord(record)}}><span><strong>{source.title}</strong><small>{new Date(source.addedAt).toLocaleDateString('zh-CN')} · 已确认共同回忆</small></span><b>+{source.contribution} 羽光</b></button>)}</div>:<p className="muted">已确认并同步的共同回忆会成为可查看的成长来源；手动互动单独记录。</p>}<ol>{store.pet.log.slice(0,6).map((entry,index)=><li key={`${index}-${entry}`}><i/><p>{entry}</p></li>)}</ol></section></div>
    {renaming && <Modal title="你想叫我什么？" onClose={() => setRenaming(false)}><form onSubmit={rename} className="life-form"><label className="field"><span>小伙伴的名字</span><input autoFocus required maxLength={12} value={name} onChange={e => setName(e.target.value)}/></label><button type="submit" className="btn primary">就叫这个名字</button></form></Modal>}
    {record && <RecordPreview record={record} onClose={() => setRecord(null)}/>}
    {journey && <Modal title="一起开始一段心愿旅程" onClose={() => setJourney(false)}>{wishes.length ? <div className="life-form"><label className="field"><span>选择日历中的心愿或计划</span><select value={journeyPlan} onChange={e => setJourneyPlan(e.target.value)}>{wishes.map(item => <option key={item.id} value={item.id}>{item.title} · {dayLabel(item.date)}</option>)}</select></label><p className="muted">关联后会记入小鹊的成长手记，原计划仍可在日历中查看和完成。</p><button className="btn primary" onClick={() => { const selected = wishes.find(item => item.id === journeyPlan); if (!selected) return;if(petAction){petAction({kind:'journey',title:selected.title});setJourney(false);return} update(s => ({ ...s, pet: { ...s.pet, curiosity: clamp(s.pet.curiosity + 8), log: [`${stamp()} · 开始心愿旅程：${selected.title}。`, ...s.pet.log].slice(0, 60) } }), '小鹊已经加入这份期待 · 好奇 +8'); setJourney(false) }}>带着小鹊一起期待</button></div> : <div className="life-form"><Empty text="还没有待完成的计划，先想一件喜欢的事吧。"/><button className="btn primary" onClick={() => { setJourney(false); go('planner'); notify('在日历与心愿中添加下一件想做的事') }}>去添加心愿</button></div>}</Modal>}
  </div>
}

const journalTypes: Journal['type'][] = ['信件', '时光胶囊', '日常', '年度回顾']
const journalIntros: Record<Journal['type'], { hint: string; title: string }> = { '信件': { hint: '有些喜欢，值得郑重写下来。', title: '写给今天的你' }, '时光胶囊': { hint: '让未来的我们，收到今天的心意。', title: '留给未来的我们' }, '日常': { hint: '那些很小的事，也很值得记住。', title: '普通又喜欢的一天' }, '年度回顾': { hint: '翻一翻那些一起走过的日子。', title: `${today().slice(0, 4)}，我们的故事` } }

export function CreatePage({ store, update, notify, intent }: PageProps) {
  const requestedType=intent?.replace(/^new:/,'') as Journal['type']
  const initialType=journalTypes.includes(requestedType)?requestedType:'信件'
  const makeJournal=(kind:Journal['type']):Journal=>({id:makeId(),title:journalIntros[kind].title,body:'',date:today(),type:kind,...(kind==='时光胶囊'?{unlockAt:`${nextDay(365)}T09:00`}:{})})
  const [type, setType] = useState<Journal['type']>(initialType)
  const [editing, setEditing] = useState<Journal | null>(()=>intent?.startsWith('new:')?makeJournal(initialType):null)
  const [preview, setPreview] = useState<Journal | null>(null)
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const [museumPreview, setMuseumPreview] = useState(false)
  const [previewRecord, setPreviewRecord] = useState<RecordItem | null>(null)
  const [includeLetters, setIncludeLetters] = useState(false)
  const [includeSources, setIncludeSources] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [year, setYear] = useState(today().slice(0, 4))
  const [secureCapsules,setSecureCapsules]=useState<SecureCapsule[]>([]),[capsuleSpace,setCapsuleSpace]=useState(''),[capsuleUser,setCapsuleUser]=useState(''),[securePreview,setSecurePreview]=useState<SecureCapsule|null>(null),[capsuleError,setCapsuleError]=useState('')
  const [capsuleVisibility,setCapsuleVisibility]=useState<'private'|'shared'>('shared')
  const [creativeOpen,setCreativeOpen]=useState(false),[creativeInstruction,setCreativeInstruction]=useState('根据我们已经确认的回忆，写一份温柔、真实、可以继续修改的草稿。'),[creativeBusy,setCreativeBusy]=useState(false),[creativeError,setCreativeError]=useState('')
  const creativeController=useRef<AbortController|null>(null)
  useEffect(()=>()=>creativeController.current?.abort(),[])
  const journals = store.journals.filter(item => !item.title.startsWith('私人草稿 · '))
  const selectedJournals = journals.filter(item => item.type === type)
  const memories = store.records.filter(item => item.status === 'confirmed' && item.kind === '回忆')
  const creativeSources=store.records.filter(canCite).slice(0,6)
  const locked = (item: Journal) => item.type === '时光胶囊' && Boolean(item.unlockAt?Date.parse(item.unlockAt)>Date.now():item.unlockDate&&item.unlockDate>today())
  const refreshCapsules=async()=>{const [session,space]=await Promise.all([formalCloud.getSession(),formalCloud.getCurrentSpace()]);if(!session.ok||!session.data||!space.ok||!space.data){setCapsuleSpace('');setCapsuleUser('');setSecureCapsules([]);return}const result=await formalCloud.capsules(space.data.space.id);if(!result.ok)throw new Error(result.error.message);setCapsuleSpace(space.data.space.id);setCapsuleUser(session.data.userId);setSecureCapsules(result.data)}
  useEffect(()=>{if(type==='时光胶囊')void refreshCapsules().catch(error=>setCapsuleError(error instanceof Error?error.message:'胶囊读取失败'))},[type])
  const newJournal = () => {if(type==='时光胶囊')setCapsuleVisibility('shared');setEditing(makeJournal(type))}
  const openSecureCapsule=async(item:SecureCapsule)=>{if(!capsuleSpace)return;const result=await formalCloud.openCapsule(capsuleSpace,item.id);if(!result.ok){setCapsuleError(result.error.message);return}setSecurePreview({...result.data,canOpen:true})}
  const removeSecureCapsule=async(item:SecureCapsule)=>{if(!capsuleSpace)return;const result=await formalCloud.deleteCapsule(capsuleSpace,item.id);if(!result.ok){setCapsuleError(result.error.message);return}await refreshCapsules();notify('安全胶囊已删除')}
  const secureCards=type==='时光胶囊'?secureCapsules.map(item=><article className={`life-journal-card ${item.canOpen?'':'is-locked'}`} key={item.id}><div className="life-journal-icon"><Icon name={item.canOpen?'mail':'lock'} size={24}/></div><div className="life-journal-copy"><span className="life-journal-meta">服务端加密胶囊 · {item.visibility==='shared'?'双方':'仅自己'}</span><h4>{item.title}</h4><p>{item.canOpen?'已到开启时间，可以读取正文。':`封存到 ${new Date(item.unlockAt).toLocaleString('zh-CN')}；正文不会在列表接口返回。`}</p><div className="life-journal-actions"><button className="btn small secondary" disabled={!item.canOpen} onClick={()=>void openSecureCapsule(item)}>{item.canOpen?'打开胶囊':'封存中'}</button>{item.ownerId===capsuleUser&&<button className="btn small" aria-label={`删除安全胶囊：${item.title}`} onClick={()=>void removeSecureCapsule(item)}><Icon name="trash" size={14}/></button>}</div></div></article>):[]
  const createWithModel=async()=>{if(!['信件','日常','年度回顾'].includes(type)||!creativeSources.length)return;const controller=new AbortController();creativeController.current=controller;setCreativeBusy(true);setCreativeError('');try{const result=await generateCreativeDraft({consent:true,type:type as '信件'|'日常'|'年度回顾',instruction:creativeInstruction,sources:creativeSources.map(record=>({id:record.id,title:record.title,body:record.body,date:record.date,kind:record.kind,status:'confirmed',sensitive:false,...(record.mediaScope==='shared'?{mediaScope:'shared' as const}:{})}))},controller.signal);setEditing({id:makeId(),title:result.title,body:result.body,type:type as '信件'|'日常'|'年度回顾',date:today()});setCreativeOpen(false);notify(`青鸟已生成可编辑草稿，引用 ${result.citationIds.length} 条已确认资料；尚未保存`)}catch(error){setCreativeError(controller.signal.aborted?'已取消生成':error instanceof Error?error.message:'生成失败')}finally{setCreativeBusy(false);if(creativeController.current===controller)creativeController.current=null}}
  const save = async (event: FormEvent) => {
    event.preventDefault()
    if (!editing || !editing.title.trim() || !editing.body.trim()) return
    if (editing.type === '时光胶囊'){
      const unlock=Date.parse(editing.unlockAt??'');if(!editing.unlockAt||!Number.isFinite(unlock)||unlock<=Date.now())return notify('请选择未来的胶囊开启时间')
      if(!capsuleSpace)return notify('安全封存需要先登录并加入共同空间；正文仍留在编辑器中。')
      const result=await formalCloud.createCapsule(capsuleSpace,{title:editing.title.trim(),body:editing.body.trim(),unlockAt:new Date(unlock).toISOString(),visibility:capsuleVisibility});if(!result.ok)return notify(result.error.message);await refreshCapsules();setEditing(null);notify('时光胶囊已加密封存；开启前服务端不会返回正文');return
    }
    const item = { ...editing, title: editing.title.trim(), body: editing.body.trim(), entityVersion: (editing.entityVersion ?? 0) + 1, expectedVersion: editing.entityVersion ?? 0 }
    update(s => ({ ...s, journals: s.journals.some(journal => journal.id === item.id) ? s.journals.map(journal => journal.id === item.id ? item : journal) : [item, ...s.journals] }), `${item.type}已保存在当前浏览器`)
    setEditing(null)
  }
  const generateReview = () => {
    const list = memories.filter(item => item.date.startsWith(year)).sort((a, b) => a.date.localeCompare(b.date))
    if (!/^\d{4}$/.test(year) || Number(year) < 1900 || Number(year) > 2200) return notify('请输入 1900—2200 之间的四位年份')
    if (!list.length) return notify(`${year} 年还没有已确认的回忆，先去记录一段吧`)
    const body = `${year} 年，我们认真记住了 ${list.length} 段时光。\n\n${list.map(item => `${dayLabel(item.date)} · ${item.title}\n${item.body}`).join('\n\n')}\n\n那些一起度过的普通日子，拼成了我们的这一年。`
    setEditing({ id: makeId(), title: `${year}，我们的故事`, body, type: '年度回顾', date: today() })
    notify('已根据已确认回忆整理成稿，可以继续修改；未调用 AI')
  }
  const doExport = async (single?: Journal) => {
    setExporting(true)
    try { await exportMuseum(single ? [] : memories, single ? [single] : includeLetters ? journals : [], includeSources); notify('离线 HTML 已生成，请查看浏览器下载') } catch { notify('导出失败，请稍后再试') } finally { setExporting(false) }
  }
  return <div className="life-page">
    <div className="life-create-hero"><div><span className="life-kicker">WORDS THAT STAY</span><h2>把想说的话，<br/>留给值得的人。</h2><p>一封信，一段日常，或一个约定好的未来。</p></div><div className="life-paper-stack" aria-hidden="true"><div><span>To you,</span><i/><i/><i/><b>♥</b></div><div/></div></div>
    <div className="life-create-layout"><section className="panel life-writing-desk"><div className="segmented life-journal-tabs">{journalTypes.map(item => <button key={item} className={item === type ? 'active' : ''} aria-pressed={item === type} onClick={() => setType(item)}>{item}</button>)}</div><div className="life-writing-heading"><div><h3>{journalIntros[type].hint}</h3><p className="muted">{type === '时光胶囊' ? '到约定的日子，再读一遍今天的心情。' : '所有文字仅保存在当前浏览器，写完也不会自动发送。'}</p></div><div className="core-inline">{type!=='时光胶囊'&&<button className="btn secondary" disabled={store.settings.aiMode!=='model'||!store.settings.aiModelConsent||!creativeSources.length} onClick={()=>{setCreativeError('');setCreativeOpen(true)}}><Icon name="model" size={16}/>青鸟辅助起草</button>}<button className="btn primary" onClick={newJournal}><Icon name="plus" size={16}/>写{type === '信件' ? '一封信' : type === '日常' ? '一段日常' : type === '时光胶囊' ? '安全时光胶囊' : '年度回顾'}</button></div></div>{type === '年度回顾' && <div className="life-review-generator"><label>回顾年份 <input aria-label="回顾年份" type="number" min="1900" max="2200" value={year} onChange={e => setYear(e.target.value)}/></label><button className="btn secondary" onClick={generateReview}>从已确认回忆生成</button><span>本地整理 · 可继续编辑</span></div>}{capsuleError&&<p role="alert" className="life-small-note">{capsuleError}</p>}<div className="life-journal-list">{secureCards}{selectedJournals.length ? selectedJournals.map(item => <article className={`life-journal-card ${locked(item) ? 'is-locked' : ''}`} key={item.id}><div className="life-journal-icon"><Icon name={item.type === '时光胶囊' ? 'lock' : item.type === '年度回顾' ? 'book' : 'mail'} size={24}/></div><div className="life-journal-copy"><span className="life-journal-meta">{item.type==='时光胶囊'?'本地旧胶囊 · 不具备安全封存':`${dayLabel(item.date)} · ${item.type}`}</span><h4>{item.title}</h4><p>{locked(item) ? `封存到 ${dayLabel(item.unlockDate ?? '')}，把期待留给那一天。` : item.body.slice(0, 84)}</p><div className="life-journal-actions"><button className="btn small secondary" onClick={() => setPreview(item)}>{locked(item) ? '查看胶囊' : '打开阅读'}</button>{!locked(item) && <button className="btn small" onClick={() => setEditing({ ...item })}>继续编辑</button>}<button className="btn small" aria-label={`删除：${item.title}`} onClick={() => setDeleteId(item.id)}><Icon name="trash" size={14}/></button></div></div></article>)  : !secureCards.length&&<Empty text={`这里还没有${type}。写下第一篇，让今天留下来。`}/>}</div></section><aside className="panel life-museum"><span className="life-kicker">可以带走的纪念</span><div className="life-museum-art" aria-hidden="true"><span>鹊信</span><strong>我们的<br/>故事集</strong><small>COLLECTED WITH LOVE</small></div><h3>离线纪念馆</h3><p>{memories.length} 段已确认回忆，做成一份可以独立打开的网页。</p><label className="life-check"><input type="checkbox" checked={includeLetters} onChange={e => setIncludeLetters(e.target.checked)}/><span>包含信件与手记</span></label><label className="life-check"><input type="checkbox" checked={includeSources} onChange={e => setIncludeSources(e.target.checked)}/><span>包含原文来源</span></label><p className="life-export-hint">私人草稿与周期记录不会导出；未到期胶囊只保留封面。</p><button className="btn secondary" onClick={() => setMuseumPreview(true)}>先看看预览</button><button className="btn primary" disabled={exporting} onClick={() => void doExport()}><Icon name="download" size={16}/>{exporting ? '正在装订…' : '生成离线纪念馆'}</button><small>文字与可读取的本地照片随文件保存</small></aside></div>
    {editing && <Modal title={store.journals.some(item => item.id === editing.id) ? `编辑${editing.type}` : `新的${editing.type}`} onClose={() => setEditing(null)} wide><form className="life-form" onSubmit={save}><label className="field"><span>标题</span><input autoFocus required maxLength={80} value={editing.title} onChange={e => setEditing({ ...editing, title: e.target.value })}/></label>{editing.type === '时光胶囊' && <><label className="field"><span>约定的开启时间</span><input required type="datetime-local" min={`${today()}T00:00`} value={editing.unlockAt||''} onChange={e=>setEditing({...editing,unlockAt:e.target.value})}/></label><label className="field"><span>到期后谁能打开</span><select value={capsuleVisibility} onChange={e=>setCapsuleVisibility(e.target.value as 'private'|'shared')}><option value="shared">我们双方</option><option value="private">仅自己</option></select><small>到期开启前，列表不会返回正文或密文。</small></label></>}<label className="field"><span>想说的话</span><textarea required rows={10} value={editing.body} onChange={e => setEditing({ ...editing, body: e.target.value })} placeholder="亲爱的你，…"/></label><div className="life-form-bottom"><span className="muted">{editing.type==='时光胶囊'?'服务端加密封存 · 开启前不返回正文':'本地保存 · 不自动发送'}</span><button className="btn primary" type="submit">{editing.type === '时光胶囊' ? '封存这份心意' : '保存这份心意'}</button></div></form></Modal>}{creativeOpen&&<Modal title="青鸟辅助起草" onClose={()=>{if(!creativeBusy)setCreativeOpen(false)}} wide><div className="life-form"><p>发送下面 {creativeSources.length} 条已确认、非私密资料的标题与正文摘要。模型只生成草稿，不会自动保存。</p><div className="life-growth-sources">{creativeSources.map(source=><div className="life-growth-source" key={source.id}><span><strong>{source.title}</strong><small>{dayLabel(source.date)} · {source.kind}</small></span></div>)}</div><label className="field"><span>想写成什么样</span><textarea rows={4} maxLength={1000} value={creativeInstruction} onChange={e=>setCreativeInstruction(e.target.value)}/></label>{creativeError&&<p role="alert" className="life-small-note">{creativeError}</p>}<div className="life-modal-actions"><button className="btn secondary" disabled={creativeBusy} onClick={()=>setCreativeOpen(false)}>只手动写</button>{creativeBusy?<button className="btn secondary" onClick={()=>creativeController.current?.abort()}>取消生成</button>:<button className="btn primary" disabled={!creativeInstruction.trim()} onClick={()=>void createWithModel()}>发送这些资料并生成草稿</button>}</div></div></Modal>}
    {preview && <JournalPreview item={preview} onClose={() => setPreview(null)} onExport={() => void doExport(preview)} exporting={exporting}/>}{securePreview&&<Modal title={securePreview.title} onClose={()=>setSecurePreview(null)} wide><article className="life-letter"><time>{new Date(securePreview.unlockAt).toLocaleString('zh-CN')} · 安全时光胶囊</time><h2>{securePreview.title}</h2><p>{securePreview.body}</p></article><div className="life-modal-actions"><button className="btn primary" onClick={()=>setSecurePreview(null)}>收好</button></div></Modal>}
    {deleteId && <Modal title="删除这份文字？" onClose={() => setDeleteId(null)}><p>删除后无法直接撤销，请确认已经保存需要的内容。</p><div className="life-modal-actions"><button className="btn secondary" onClick={() => setDeleteId(null)}>再留一会儿</button><button className="btn danger" onClick={() => { update(s => ({ ...s, journals: s.journals.filter(item => item.id !== deleteId) }), '已删除'); setDeleteId(null) }}>确认删除</button></div></Modal>}
    {museumPreview && <Modal title="我们的离线纪念馆 · 预览" onClose={() => setMuseumPreview(false)} wide><div className="life-museum-preview"><span className="life-kicker">COLLECTED WITH LOVE</span><h2>普通日子，也值得珍藏。</h2><p>{memories.length} 段回忆{includeLetters ? `，${journals.length} 篇写给彼此的话` : ''}。</p>{memories.map(item => <button key={item.id} onClick={() => { setPreviewRecord(item); setMuseumPreview(false) }}>{item.image && <img src={item.image} alt=""/>}<span><time>{dayLabel(item.date)}</time><strong>{item.title}</strong><small>{item.body.slice(0, 60)}</small></span></button>)}{includeLetters && <div className="life-museum-letters"><h3>写给彼此的话</h3>{journals.map(item => <p key={item.id}><strong>{item.title}</strong> · {locked(item) ? `封存至 ${dayLabel(item.unlockDate ?? '')}` : item.type}</p>)}</div>}<button className="btn primary" disabled={exporting} onClick={() => void doExport()}>{exporting ? '正在导出…' : '下载这份纪念馆'}</button></div></Modal>}
    {previewRecord && <RecordPreview record={previewRecord} onClose={() => { setPreviewRecord(null); setMuseumPreview(true) }}/>}
  </div>
}

function JournalPreview({ item, onClose, onExport, exporting }: { item: Journal; onClose: () => void; onExport: () => void; exporting: boolean }) {
  const locked=item.type==='时光胶囊'&&Boolean(item.unlockAt?Date.parse(item.unlockAt)>Date.now():item.unlockDate&&item.unlockDate>today()),unlock=item.unlockAt?new Date(item.unlockAt).toLocaleString('zh-CN'):dayLabel(item.unlockDate??'')
  return <Modal title={item.title} onClose={onClose} wide>{locked?<div className="life-locked-capsule"><div className="life-envelope-art" aria-hidden="true"><span>♥</span></div><h3>这是旧版本地胶囊。</h3><p>页面约定在 <strong>{unlock}</strong> 开启，但正文仍存在当前浏览器数据中，不具备服务端安全封存。</p><small>请登录共同空间后重新创建安全胶囊。新版不再提供“演示提前预览”。</small></div>:<article className="life-letter"><time>{dayLabel(item.date)} · {item.type}</time><h2>{item.title}</h2><p>{item.body}</p></article>}<div className="life-modal-actions"><button className="btn secondary" onClick={onClose}>收好</button><button className="btn primary" disabled={exporting} onClick={onExport}><Icon name="download" size={16}/>{exporting?'正在导出…':locked?'导出不含正文的封面':'导出这篇文字'}</button></div></Modal>
}

export function SettingsPage(props: PageProps) {
  const { store, update, notify, intent } = props
  const [tab, setTab] = useState<'appearance' | 'space' | 'data' | 'logs'>(intent === 'space' || intent === 'data' || intent === 'logs' ? intent : 'appearance')
  const [selfName, setSelfName] = useState(store.settings.selfName)
  const [partnerName, setPartnerName] = useState(store.settings.partnerName)
  const [since, setSince] = useState(store.settings.since)
  const profileEditing=useRef(false)
  const [restore, setRestore] = useState<DemoStore | null>(null)
  const [resetStep, setResetStep] = useState(0)
  const [resetText, setResetText] = useState('')
  const fileInput = useRef<HTMLInputElement>(null)
  const [modelConfig,setModelConfig]=useState<AssistantModelConfig|null>(null)
  useEffect(()=>{let active=true;void getAssistantModelConfig().then(value=>{if(active)setModelConfig(value)}).catch(()=>{if(active)setModelConfig(null)});return()=>{active=false}},[])
  const chooseTheme = (themeId: DemoStore['settings']['theme']) => {
    const room = themeId === 'cosmos' ? 'cosmos' : themeId === 'bamboo' || themeId === 'jade' ? 'garden' : 'study'
    const selected = themeOptions.find(theme => theme.id === themeId)
    update(s => ({ ...s, settings: { ...s.settings, theme: themeId }, pet: props.petAction?s.pet:{ ...s.pet, room } }), `已切换到「${selected?.name ?? themeId}」`)
  }
  const setSetting = <K extends keyof DemoStore['settings']>(key: K, value: DemoStore['settings'][K], message: string) => update(s => ({ ...s, settings: { ...s.settings, [key]: value } }), message)
  useEffect(()=>{if(profileEditing.current)return;setSelfName(store.settings.selfName);setPartnerName(store.settings.partnerName);setSince(store.settings.since)},[store.settings.selfName,store.settings.partnerName,store.settings.since])
  const saveProfile = (event: FormEvent) => { event.preventDefault(); if (!selfName.trim() || !partnerName.trim()) return;profileEditing.current=false;if(props.petAction){props.petAction({kind:'profile',profile:{selfName:selfName.trim(),partnerName:partnerName.trim(),since}});notify('共同资料已提交，正在同步');return} update(s => ({ ...s, settings: { ...s.settings, selfName: selfName.trim(), partnerName: partnerName.trim(), since } }), '空间资料已保存') }
  const loadBackup = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (!file) return
    if (file.size > 20 * 1024 * 1024) return notify('备份文件过大，请选择 20 MB 以内的 JSON 文件')
    try { const value: unknown = JSON.parse(await file.text()); if (!isDemoStore(value)) throw new Error('invalid'); setRestore(value) } catch { notify('文件不是有效的鹊信备份，当前数据未改变') }
  }
  return <div className="life-page life-settings">
    <div className="life-intro"><span className="life-kicker">MAKE IT FEEL LIKE YOU</span><h2>让这个空间，更像你们。</h2><p>喜欢的模样、舒适的边界，都由你来决定。</p></div>
    <div className="life-settings-tabs">{[{ id: 'appearance' as const, label: '外观与主题', icon: 'palette' }, { id: 'space' as const, label: '空间与功能', icon: 'settings' }, { id: 'data' as const, label: '数据与备份', icon: 'database' }, { id: 'logs' as const, label: '操作记录', icon: 'clock' }].map(item => <button key={item.id} className={tab === item.id ? 'active' : ''} onClick={() => setTab(item.id)}><Icon name={item.icon} size={17}/>{item.label}</button>)}</div>
    {tab === 'appearance' && <><section className="panel life-theme-section"><div className="panel-heading"><div><span className="life-kicker">十种心情，一个家</span><h3>选择你们的空间主题</h3></div><span className="tag">随时切换 · 本地保存</span></div><div className="life-theme-grid">{themeOptions.map((theme, index) => <button key={theme.id} className={`life-theme-card theme-mini-${theme.id} ${store.settings.theme === theme.id ? 'is-selected' : ''}`} style={{ '--preview-bg': theme.colors[0], '--preview-accent': theme.colors[1], '--preview-soft': theme.colors[2] } as CSSProperties} aria-pressed={store.settings.theme === theme.id} onClick={() => chooseTheme(theme.id)}><div className="life-theme-preview"><div className="life-theme-mini-nav"><b>鹊</b><i/><i/><i/></div><div className="life-theme-mini-content"><div className="life-theme-mini-title"/><div className="life-theme-mini-hero"><span>{['笺', '墨', 'Hi', '竹', '✦', '玉', '☀', '松', '▣', '山'][index]}</span><i/></div><div className="life-theme-mini-cards"><i/><i/><i/></div></div><span className="life-theme-check">✓</span></div><div className="life-theme-label"><strong>{theme.name}</strong><span>{theme.colors.map(color => <i key={color} style={{ background: color }}/>)}</span></div><small>{theme.desc}</small></button>)}</div></section><section className="panel life-setting-row"><div><strong>减少动态效果</strong><p>关闭宠物跳跃和装饰动画，让界面更安静。</p></div><label className="life-toggle"><input type="checkbox" aria-label="减少动态效果" checked={store.settings.reduceMotion} onChange={e => setSetting('reduceMotion', e.target.checked, e.target.checked ? '已减少动态效果' : '已恢复动态效果')}/><span/></label></section></>}
    {tab === 'space' && <div className="life-settings-grid"><section className="panel life-profile" aria-label="空间资料"><div className="panel-heading"><div><span className="life-kicker">关于我们</span><h3>空间资料</h3></div><Icon name="heart" size={20}/></div><p className="muted">{props.petAction?'双方称呼和纪念日期共同保存；主题与私人草稿各自独立。':'资料仅保存在当前本地空间。'}</p><form onSubmit={saveProfile} onChange={()=>{profileEditing.current=true}} className="life-form"><div className="form-grid"><label className="field"><span>你的称呼</span><input required maxLength={16} value={selfName} onChange={e => setSelfName(e.target.value)}/></label><label className="field"><span>对方的称呼</span><input required maxLength={16} value={partnerName} onChange={e => setPartnerName(e.target.value)}/></label></div><label className="field"><span>故事开始的日期</span><input type="date" required max={today()} value={since} onChange={e => setSince(e.target.value)}/></label><button className="btn primary" type="submit">保存资料</button></form></section><section className="panel life-ai-settings"><span className="life-kicker">青鸟助手</span><h3>整理方式</h3><p className="muted">本地检索不会发送资料。真实模型仅发送你每次确认的已匹配片段，密钥保存在服务端。</p><label className="life-radio"><input type="radio" name="aiMode" checked={store.settings.aiMode === 'demo'} onChange={() => setSetting('aiMode', 'demo', '已开启本地规则整理')}/><span><strong>只用本地规则</strong><small>候选和问答均不调用外部模型</small></span></label><label className="life-radio"><input type="radio" name="aiMode" disabled={!modelConfig?.enabled} checked={store.settings.aiMode === 'model'} onChange={() => setSetting('aiMode', 'model', '已选择真实模型；每次发送前仍需确认资料范围')}/><span><strong>真实模型{modelConfig?.enabled?` · ${modelConfig.model}`:' · 服务端未配置'}</strong><small>结构化答案、引用校验、超时与取消保护</small></span></label>{store.settings.aiMode==='model'&&<label className="core-checkbox"><input type="checkbox" checked={Boolean(store.settings.aiModelConsent)} onChange={e=>setSetting('aiModelConsent',e.target.checked,e.target.checked?'已同意在每次确认后发送所列片段':'已关闭模型资料发送')}/><span>允许把每次发送前列出的已确认、非私密片段交给配置的模型服务<small>问题文字也会发送；私人、待确认和已忽略内容不会发送。</small></span></label>}<label className="life-radio"><input type="radio" name="aiMode" checked={store.settings.aiMode === 'off'} onChange={() => setSetting('aiMode', 'off', '已关闭自动整理')}/><span><strong>关闭自动整理</strong><small>只使用手动记录和管理功能</small></span></label></section><section className="panel life-module-settings"><div className="panel-heading"><div><span className="life-kicker">按喜欢的方式使用</span><h3>模块与演示开关</h3></div></div>{[{ key: 'moduleCare' as const, title: '日常关怀', desc: '需要表达、私人草稿与重要事情跟进' }, { key: 'modulePet' as const, title: '鹊巢电子宠物', desc: '一个可以慢慢照顾的小伙伴' }, { key: 'wechatDemo' as const, title: '微信入口演示', desc: '仅切换示意界面，不连接微信或读取聊天' }].map(item => <div className="life-setting-row" key={item.key}><div><strong>{item.title}</strong><p>{item.desc}</p></div><label className="life-toggle"><input type="checkbox" aria-label={item.title} checked={store.settings[item.key]} onChange={e => setSetting(item.key, e.target.checked, `${item.title}已${e.target.checked ? '开启' : '关闭'}${item.key.endsWith('Demo') ? '；未连接真实服务' : ''}`)}/><span/></label></div>)}</section><SyncLab {...props}/></div>}
    {tab==='space'&&<AssistantCapabilities mode={store.settings.aiMode} consent={Boolean(store.settings.aiModelConsent)} config={modelConfig} notify={notify}/>} 
    {tab === 'data' && <div className="life-settings-grid"><section className="panel life-backup"><span className="life-kicker">把故事握在自己手里</span><h3>备份与恢复</h3><p>JSON 备份包含记录、私人草稿、周期日期、设置和宠物状态。请把文件保存在自己信任的位置。</p><div className="life-backup-stats"><div><strong>{store.records.length}</strong><span>条记录</span></div><div><strong>{store.journals.length}</strong><span>篇文字</span></div><div><strong>{store.plans.length}</strong><span>个计划</span></div></div><div className="life-button-row"><button className="btn primary" onClick={() => { exportBackup(store); notify('JSON 备份已生成，请查看浏览器下载') }}><Icon name="download" size={16}/>导出完整备份</button><button className="btn secondary" onClick={() => fileInput.current?.click()}><Icon name="upload" size={16}/>恢复备份</button><input className="life-hidden-input" ref={fileInput} type="file" accept="application/json,.json" onChange={event => void loadBackup(event)} aria-label="选择 JSON 备份文件"/></div><p className="life-small-note">恢复前会验证文件，并再次请你确认。恢复将替换当前浏览器中的数据。</p></section><section className="panel life-storage-info"><Icon name="lock" size={30}/><h3>此刻，故事只在这里</h3><p>记录、计划、文字和设置分别保存在当前浏览器的 IndexedDB 资料库中。刷新页面会保留，清除网站数据会删除。</p><p>未连接账号时，资料只保存在此浏览器。连接本机共同空间后，已确认的非私密资料可同步到本机服务端；私人草稿仍留在个人资料中。真实 AI 和微信直连尚未接入。</p><span className="tag">本地优先 · 共享范围可查看</span></section><section className="panel life-reset"><div><h3>重新体验示例</h3><p className="muted">恢复初始示例会替换所有本地修改。建议先导出备份。</p></div><button className="btn danger" onClick={() => { setResetStep(1); setResetText('') }}>重置示例数据</button></section></div>}
    {tab === 'logs' && <section className="panel life-logs"><div className="panel-heading"><div><span className="life-kicker">每一步，都可以回看</span><h3>本地操作记录</h3></div><span className="tag">{store.logs.length} 条</span></div>{store.logs.length ? <ol>{store.logs.map(item => <li key={item.id}><span className="life-log-dot"/><time>{item.time}</time><p>{item.text}</p></li>)}</ol> : <Empty text="还没有操作记录。"/>}<p className="muted">这些是当前浏览器中的演示操作记录，不代表云端或外部服务运行结果。</p></section>}
    {restore && <Modal title="恢复这份备份？" onClose={() => setRestore(null)}><p>这份备份包含 <strong>{restore.records.length}</strong> 条记录、<strong>{restore.journals.length}</strong> 篇文字和 <strong>{restore.plans.length}</strong> 个计划。</p><p className="muted">恢复会替换当前浏览器的数据，包括私人内容、设置和宠物状态。</p><div className="life-modal-actions"><button className="btn secondary" onClick={() => { exportBackup(store); notify('已导出当前数据的备份') }}>先备份当前数据</button><button className="btn primary" onClick={() => { update(() => structuredClone(restore), '备份已恢复'); setSelfName(restore.settings.selfName); setPartnerName(restore.settings.partnerName); setSince(restore.settings.since); setRestore(null) }}>确认恢复</button></div></Modal>}
    {resetStep > 0 && <Modal title={resetStep === 1 ? '重新载入示例数据？' : '最后确认：替换当前数据'} onClose={() => setResetStep(0)}>{resetStep === 1 ? <><p>你添加的记录、文字、计划和设置会被初始示例替换。</p><div className="life-modal-actions"><button className="btn secondary" onClick={() => { exportBackup(store); notify('当前数据已导出') }}>先导出备份</button><button className="btn danger" onClick={() => setResetStep(2)}>继续重置</button></div></> : <div className="life-form"><label className="field"><span>输入“重置”，确认替换当前数据</span><input autoFocus value={resetText} onChange={e => setResetText(e.target.value)} placeholder="重置"/></label><button className="btn danger" disabled={resetText !== '重置'} onClick={() => { update(() => structuredClone(initialStore), '已恢复初始示例'); setSelfName(initialStore.settings.selfName); setPartnerName(initialStore.settings.partnerName); setSince(initialStore.settings.since); setResetStep(0) }}>确认重置</button></div>}</Modal>}
  </div>
}
